24	function legendSelectActionHandler(methodName, payload, ecModel) {
25	    const selectedMap = {};
26	    const isToggleSelect = methodName === 'toggleSelected';
27	    let isSelected;
28	    // Update all legend components
29	    ecModel.eachComponent('legend', function (legendModel) {
30	        if (isToggleSelect && isSelected != null) {
31	            // Force other legend has same selected status
32	            // Or the first is toggled to true and other are toggled to false
33	            // In the case one legend has some item unSelected in option. And if other legend
34	            // doesn't has the item, they will assume it is selected.
35	            legendModel[isSelected ? 'select' : 'unSelect'](payload.name);
36	        }
37	        else if (methodName === 'allSelect' || methodName === 'inverseSelect') {
38	            legendModel[methodName]();
39	        }
40	        else {
41	            legendModel[methodName](payload.name);
42	            isSelected = legendModel.isSelected(payload.name);
43	        }
44	        const legendData = legendModel.getData();
45	        each(legendData, function (model) {
46	            const name = model.get('name');
47	            // Wrap element
48	            if (name === '\n' || name === '') {
49	                return;
50	            }
51	            const isItemSelected = legendModel.isSelected(name);
52	            if (selectedMap.hasOwnProperty(name)) {
53	                // Unselected if any legend is unselected
54	                selectedMap[name] = selectedMap[name] && isItemSelected;
55	            }
56	            else {
57	                selectedMap[name] = isItemSelected;
58	            }
59	        });
60	    });
61	    // Return the event explicitly
62	    return (methodName === 'allSelect' || methodName === 'inverseSelect')
63	        ? {
64	            selected: selectedMap
65	        }
66	        : {
67	            name: payload.name,
68	            selected: selectedMap
69	        };
70	}
