    registers.registerAction(
        'legendToggleSelect', 'legendselectchanged',
        curry(legendSelectActionHandler, 'toggleSelected')
    );

    registers.registerAction(
        'legendAllSelect', 'legendselectall',
        curry(legendSelectActionHandler, 'allSelect')
