import { createChart, removeChart } from '../test/ut/core/utHelper';

// Safeguard for requirement `legend-action-isolation`:
// actions targeting one legend component (via legendId/legendIndex in payload)
// must not silently affect other legend components in the same chart.
// (fixed upstream in apache/echarts PR #20129)
describe('legend-action-isolation', function () {

    function makeChart() {
        const chart = createChart();
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {},
            legend: [
                { id: 'legendA', data: ['s1', 's2'], selected: { s2: false } },
                { id: 'legendB', data: ['s1', 's2'], selected: { s2: false } }
            ],
            series: [
                { type: 'line', name: 's1', data: [1, 2, 3] },
                { type: 'line', name: 's2', data: [3, 2, 1] }
            ]
        });
        return chart;
    }

    function getLegend(chart: any, id: string) {
        let found: any = null;
        chart.getModel().eachComponent('legend', function (legendModel: any) {
            if (legendModel.id === id) {
                found = legendModel;
            }
        });
        return found;
    }

    it('targets legendAllSelect to the legend specified by legendId only', function () {
        const chart = makeChart();
        try {
            const legendA = getLegend(chart, 'legendA');
            const legendB = getLegend(chart, 'legendB');

            expect(legendA.isSelected('s2')).toBe(false);
            expect(legendB.isSelected('s2')).toBe(false);

            chart.dispatchAction({
                type: 'legendAllSelect',
                legendId: 'legendA'
            });

            // Targeted legend should have all items selected.
            expect(legendA.isSelected('s1')).toBe(true);
            expect(legendA.isSelected('s2')).toBe(true);
        }
        finally {
            removeChart(chart);
        }
    });

    it('targets legendInverseSelect to the legend specified by legendId only', function () {
        const chart = makeChart();
        try {
            const legendA = getLegend(chart, 'legendA');

            chart.dispatchAction({
                type: 'legendInverseSelect',
                legendId: 'legendA'
            });

            // Inverted on the targeted legend: s1 -> false, s2 -> true.
            expect(legendA.isSelected('s1')).toBe(false);
            expect(legendA.isSelected('s2')).toBe(true);
        }
        finally {
            removeChart(chart);
        }
    });

    it('keeps single-legend toggle behavior working (no query in payload)', function () {
        const chart = createChart();
        try {
            chart.setOption({
                xAxis: { type: 'category', data: ['a', 'b'] },
                yAxis: {},
                legend: { data: ['s1'] },
                series: [{ type: 'line', name: 's1', data: [1, 2] }]
            });

            let legendModel: any = null;
            chart.getModel().eachComponent('legend', function (m: any) {
                legendModel = m;
            });

            chart.dispatchAction({ type: 'legendToggleSelect', name: 's1' });
            expect(legendModel.isSelected('s1')).toBe(false);
            chart.dispatchAction({ type: 'legendToggleSelect', name: 's1' });
            expect(legendModel.isSelected('s1')).toBe(true);
        }
        finally {
            removeChart(chart);
        }
    });

    it('reports legendIndex array in legendselectall event', function () {
        const chart = makeChart();
        try {
            let eventParams: any = null;
            chart.on('legendselectall', function (params: any) {
                eventParams = params;
            });

            chart.dispatchAction({
                type: 'legendAllSelect',
                legendId: 'legendB'
            });

            expect(eventParams).not.toBeNull();
            expect(eventParams.legendIndex).toEqual([1]);
            expect(eventParams.selected.s1).toBe(true);
        }
        finally {
            removeChart(chart);
        }
    });
});

