describe('legend-action-isolation', function () {

    // Two legends; 's2' is intentionally shared to check the same-name sync,
    // 's1' / 's3' are exclusive to one legend and must stay isolated.
    function makeChart() {
        const chart = createChart();
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {},
            legend: [
                { id: 'legendA', data: ['s1', 's2'], selected: { s2: false } },
                { id: 'legendB', data: ['s2', 's3'], selected: { s2: false, s3: false } }
            ],
            series: [
                { type: 'line', name: 's1', data: [1, 2, 3] },
                { type: 'line', name: 's2', data: [3, 2, 1] },
                { type: 'line', name: 's3', data: [2, 1, 2] }
            ]
        });
        return chart;
    }

    function getLegend(chart: any, id: string) {
        let found: any = null;
